	playStarCollect(comboCount = 0) {
		if (!this.soundEnabled) return;
		this.init();
		if (!this.ctx) return;
		const scale = [
			523.25,
			587.33,
			659.25,
			783.99,
			880,
			1046.5,
			1174.66,
			1318.51
		];
		const noteFreq = scale[Math.min(comboCount, scale.length - 1)];
		const now = this.ctx.currentTime;
		const osc = this.ctx.createOscillator();
		const overtone = this.ctx.createOscillator();
		const gain = this.ctx.createGain();
		osc.type = "sine";
		osc.frequency.setValueAtTime(noteFreq, now);
		overtone.type = "sine";
		overtone.frequency.setValueAtTime(noteFreq * 2, now);
		gain.gain.setValueAtTime(.12, now);
		gain.gain.exponentialRampToValueAtTime(.001, now + .22);
		osc.connect(gain);
		overtone.connect(gain);
		gain.connect(this.sfxOut || this.ctx.destination);
		osc.start(now);
		overtone.start(now);
		osc.stop(now + .24);
		overtone.stop(now + .24);
	}
