function hasCraftedTool(tools, id) {
	return !!tools?.some((t) => t.id === id && (t.level ?? 1) >= 1);
}
function homeUpgradeCostMultiplier(tools) {
	let m = 1;
	if (hasCraftedTool(tools, "SOLAR_WELDER")) m *= .8;
	if (hasCraftedTool(tools, "GRAVITON_HAMMER")) m *= .85;
	return m;
}
function gardenGrowthMultiplier(tools) {
	return hasCraftedTool(tools, "STARLIGHT_CAN") ? .67 : 1;
}
function gardenHarvestMultiplier(tools, harvestSkillRank = 0) {
	let m = 1 + harvestSkillRank * .15;
	if (hasCraftedTool(tools, "STAR_SICKLE")) m *= 1.4;
	return m;
}
